\begin{lemma}[Pasting two consistent measurements; Fact 4.35 in \cite{Natarajan2018NEEXP}]\label{lem:pasting}
	\lean{MIPStarRE.QPBT.pastedMeasurement}
	\lean{MIPStarRE.QPBT.exists_pasting_error}
