\begin{lemma}[Schmidt coordinates for a square coefficient matrix]
	\label{lem:pasting-schmidt-coordinates}
	\lean{MIPStarRE.QPBT.exists_schmidt_coordinates, MIPStarRE.QPBT.schmidtCoordinates_spec}
	\leanok
	Every square complex matrix $C$ has a decomposition
	$C=U\operatorname{diag}(s_i)V^*$ with unitary $U,V$ and $s_i\geq0$.
	Zero singular values are allowed. This is a formalization-only construction
	for the argument in \cite{gap:qpbt_pasting-product-error}.
\end{lemma}
\begin{proof}
	\leanok
	Diagonalize $C^*C$, normalize the images of its positive-eigenvalue
	eigenvectors, and complete this orthonormal family on the left. The
	zero-eigenvalue eigenvectors are annihilated by $C$.
\end{proof}

\begin{definition}[The state-dependent Schmidt mirror]
	\label{def:pasting-schmidt-mirror}
	\lean{MIPStarRE.QPBT.schmidtCoefficientMatrix, MIPStarRE.QPBT.schmidtCoordinates, MIPStarRE.QPBT.schmidtMirrorUnitary, MIPStarRE.QPBT.schmidtMirror}
	\leanok
	\uses{lem:pasting-schmidt-coordinates}
	For any bipartite vector $\psi$, form its coefficient matrix
	$C_{ij}=\psi_{ij}$ and choose Schmidt coordinates
	$C=U\operatorname{diag}(s_i)V^*$ once for that vector. For a Bob operator
	$B$, define the Alice operator
	$\widetilde B=UV^*B^TVU^*$.
	This auxiliary operator does not replace any measurement in the statement
	of Lemma~\ref{lem:pasting}.
\end{definition}

\begin{lemma}[Schmidt-mirror norm estimate]
	\label{lem:pasting-schmidt-mirror-norm}
	\lean{MIPStarRE.QPBT.schmidt_diagonal_mirror_estimate, MIPStarRE.QPBT.schmidt_action_norm_sq, MIPStarRE.QPBT.schmidtMirror_norm_sq_le}
	\leanok
	\uses{def:pasting-schmidt-mirror, lem:pasting-schmidt-pair}
	For every bipartite vector $\psi$ and Hermitian operators $H,B$,
	\[
		\|(\widetilde B\ot\Id-\Id\ot B)\psi\|^2
		\leq 2\|(H\ot\Id-\Id\ot B)\psi\|^2.
