\begin{lemma}[Cross move with independent opposite-register effects]
	\label{lem:pasting-distinct-cross-move}
	\lean{MIPStarRE.QPBT.abs_cross_move_gap_le_sqrt_distinct_families}
	\leanok
	\uses{def:pasting-tensor-placement, def:povm-conventions}
	Let $P,G,H$ be measurements, with $G,H$ indexed by the same codewords,
	and let $\psi$ be a unit vector. Then
	\begin{align*}
	 &\left|\sum_{a,g}\langle\psi|\Id\ot G_gP_aG_gP_a|\psi\rangle
	   -\sum_{g,a}\langle\psi|H_g\ot P_aG_gP_a|\psi\rangle\right|\\
	 &\qquad\leq
	 \sqrt{\sum_g\|(\Id\ot G_g-H_g\ot\Id)\psi\|^2}.
	\end{align*}
	No equality between the two codeword families is assumed.
\end{lemma}
\begin{proof}
	\leanok
	Expand the difference as an inner product of the moved vectors with the
	cross vectors. Measurement contraction and Cauchy--Schwarz give the bound.
\end{proof}

\begin{lemma}[Collision bounds for independent opposite-register families]
	\label{lem:pasting-distinct-collisions}
	\lean{MIPStarRE.QPBT.consistencyDefect_codeword_fine_le_coarse_add_distinct_families, MIPStarRE.QPBT.avgOver_pinched_collision_le_distinct_families}
	\leanok
	\uses{lem:pasting-collision-averaging, def:povm-conventions}
	Let $G^x,H^x$ be measurements indexed by the same second codewords,
	let $P^{x,y_1}$ be a measurement, and let $\psi$ be a unit vector.
	Assume a probability law $\mathcal D$ and the conditional collision bound
	of Lemma~\ref{lem:pasting}, with $\eta\geq0$.
	The fine consistency defect between $H$ on Alice and $G$ on Bob is at most
	the corresponding coarse defect plus $\eta$. Moreover,
	\[
	 \Exp_{\mathcal D}\sum_{g\ne h:\,g(y_2)=h(y_2)}\sum_a
	 \langle\psi|H^x_h\ot P^{x,y_1}_aG^x_gP^{x,y_1}_a|\psi\rangle
	 \leq\eta.
	\]
	suffices to bound the difference of the two overlaps at a fixed question.
	The second codeword effects being idempotent and summing to the identity,
	$P_{a_1} - \sum_{g_2} G_{g_2} P_{a_1} G_{g_2}
	= \sum_{g_2} [P_{a_1}, G_{g_2}] G_{g_2}$, and the answer effects being
	idempotent, $A_{a_1} \ot [P_{a_1}, G_{g_2}] G_{g_2}
	= (A_{a_1} \ot [P_{a_1}, G_{g_2}]) (A_{a_1} \ot G_{g_2})$. The commutator is
	anti-self-adjoint, so the quadratic form of that product is the real part of
	the inner product of the two applied vectors, and the Cauchy--Schwarz
	inequality over the pairs $(a_1, g_2)$ bounds the difference by the product
	of the two square roots. The second factor is at most $1$, the operators
	$A_{a_1} \ot G_{g_2}$ being the effects of a measurement; in the first factor
	the answer effect is dropped, which leaves the square root of the commutator
	mass at that question. Jensen's inequality for the square root gives the
	averaged form.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-cross-move}
	\lean{MIPStarRE.QPBT.abs_cross_move_gap_le_sqrt}
	\leanok
	\uses{def:pasting-tensor-placement}
	Let $P_{a_1}$ and $G_{g_2}$ be measurements placed on the second tensor
	factor and let $\ket{\psi}$ be a unit vector. Then
	\[
		\Bigl| \sum_{a_1, g_2} \bra{\psi} \Id \ot G_{g_2} P_{a_1} G_{g_2} P_{a_1}
			\ket{\psi} - \sum_{g_2} \bra{\psi} G_{g_2} \ot \sum_{a_1} P_{a_1}
			G_{g_2} P_{a_1} \ket{\psi} \Bigr| \le \Bigl( \sum_{g_2} \bigl\|
			(\Id \ot G_{g_2} - G_{g_2} \ot \Id) \ket{\psi} \bigr\|^2
		\Bigr)^{1/2}\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-tensor-placement}
	Each summand on the left is the overlap of
	$(\Id \ot P_{a_1} G_{g_2}) \ket{\psi}$ with
	$(\Id \ot G_{g_2} P_{a_1}) \ket{\psi}$, and each summand on the right is the
	overlap of $(G_{g_2} \ot P_{a_1}) \ket{\psi}$ with the same vector. The
	difference of the two left vectors is the first family applied on the second
	factor to the difference of the two placements of the second family, so the
	Cauchy--Schwarz inequality over the pairs $(a_1, g_2)$ bounds the gap by the
	product of two square roots. The effects of a measurement placed on one
	factor contract total squared norm, so the first factor is at most the
	summed squared distance between the two placements of the second family, and
	the second factor is at most $\|\psi\|^2 = 1$.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-commutator-expansion}
	\lean{MIPStarRE.QPBT.commutator_mass_eq_expansion}
	\leanok
	\uses{def:pasting-tensor-placement}
	Let $P_{a_1}$ be a measurement and $G_{g_2}$ a projective measurement, both
	placed on the second tensor factor. Then
	\[
		\sum_{a_1, g_2} \bigl\| (\Id \ot [P_{a_1}, G_{g_2}]) \ket{\psi} \bigr\|^2
		= \sum_{a_1, g_2} \bigl\| (\Id \ot P_{a_1} G_{g_2}) \ket{\psi} \bigr\|^2
			+ \sum_{a_1} \bra{\psi} \Id \ot P_{a_1}^2 \ket{\psi}
			- 2 \sum_{a_1, g_2} \bra{\psi} \Id \ot G_{g_2} P_{a_1} G_{g_2} P_{a_1}
				\ket{\psi}\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-tensor-placement}
	Expand the squared norm of a difference at each pair: it is the sum of the
	two squared norms minus twice the real part of the overlap of the two
	vectors. The second squared norm is the expectation of
	$P_{a_1} G_{g_2} P_{a_1}$, the second family being idempotent, and summing
	over the codewords replaces the codeword effect by the identity, which
	leaves the expectation of $P_{a_1}^2$. The overlap of the two vectors is the
	expectation of $G_{g_2} P_{a_1} G_{g_2} P_{a_1}$, the effects of a
	measurement being self-adjoint.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-ordered-product-mass}
	\lean{MIPStarRE.QPBT.sum_norm_ordered_product_le_one}
